const number=(n:any)=>new Intl.NumberFormat('uz-UZ').format(Number(n)||0);
const isoDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tashkent',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
