 const save=useCallback(async(entity:string,data:Record<string,any>,record?:RecordRow,action?:string)=>{const response=await fetch('/api/crm/records',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({entity,data,id:record?.id,version:record?.version,action:action??(record?'update':'create')})});const result:any=await response.json();if(!response.ok)throw Error(result.error||'Saqlanmadi');setRecords(prev=>[result.record,...prev.filter(r=>r.id!==result.record.id)]);setEvents(prev=>[result.event??{record_id:result.record.id,action:action??(record?'update':'create'),entity,created_at:result.record.updated_at},...prev]);if(entity==='transactions'&&!record&&!action&&result.record.data.direction==='Kirim')requestReceipt(result.record,records.find(r=>r.id===result.record.data.student)?.data.name||'');if(['attendance','coins'].includes(entity))void reload();return result.record as RecordRow},[records,reload]);
 useEffect(()=>{const context=(document as any).modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();const tools=[{name:'list_crm_records',description:'Joriy foydalanuvchining CRM yozuvlarini o‘qish.',inputSchema:{type:'object',properties:{entity:{type:'string'}},required:['entity'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async(input:any)=>{if(typeof input?.entity!=='string'||!pages.some(p=>p.entity===input.entity))throw Error('Noto‘g‘ri bo‘lim');const r=await fetch('/api/crm/records');if(!r.ok)throw Error('Yuklanmadi');const d:any=await r.json();return d.records.filter((x:RecordRow)=>x.entity===input.entity&&!x.deleted)}},{name:'start_crm_record_creation',description:'Yozuv yaratish formasini ochadi; yozuvni saqlamaydi.',inputSchema:{type:'object',properties:{path:{type:'string'}},required:['path'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async(input:any)=>{const p=findPage(input?.path);if(!p||!p.fields.length||p.readonly)throw Error('Bu sahifada yaratish mavjud emas');router.push(p.path);setEdit({page:p});return {opened:true,path:p.path}}}];for(const tool of tools)Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});return()=>lifecycle.abort()},[router]);
 const label=useCallback((id:any)=>{const r=records.find(r=>r.id===id);return r?[r.data.name,r.data.surname].filter(Boolean).join(' ')||r.data.note||'Yozuv':String(id??'—')},[records]);
 const filtered=useMemo(()=>{let rows=records.filter(r=>r.entity===page.entity&&(page.kind==='cancelled'||showArchive?!!r.deleted:!r.deleted));if(page.filter==='new')rows=rows.filter(r=>Date.now()-new Date(r.created_at).getTime()<30*86400000);else if(page.filter==='trial')rows=rows.filter(r=>!!r.data.date&&r.data.status!=='Bekor qilindi');else if(page.filter)rows=rows.filter(r=>(r.data.status||'Faol')===page.filter);if(branch!=='all')rows=rows.filter(r=>scopeToBranch(records,branch).some(s=>s.id===r.id));if(statusFilter!=='all')rows=rows.filter(r=>r.data.status===statusFilter||r.data.direction===statusFilter);if(groupFilter!=='all')rows=rows.filter(r=>r.entity==='students'?groupIds(r,active).includes(groupFilter):r.data.group===groupFilter);if(dateFrom)rows=rows.filter(r=>(r.data.date||r.created_at).slice(0,10)>=dateFrom);if(dateTo)rows=rows.filter(r=>(r.data.date||r.created_at).slice(0,10)<=dateTo);if(query)rows=rows.filter(r=>Object.values(r.data).some(v=>label(v).toLowerCase().includes(query.toLowerCase())));return rows},[records,page,branch,statusFilter,groupFilter,dateFrom,dateTo,query,label,showArchive]);
 const pageSize=Math.min(100,Math.max(10,Number(active.find(r=>r.entity==='settings'&&r.data.section==='system')?.data.tablePageSize)||20));
