function EmptyState({title='Ma’lumotlar mavjud emas',text='Yangi yozuv qo‘shish uchun “Qo‘shish” tugmasini bosing.'}:{title?:string;text?:string}){return <Empty className="empty-state"><EmptyHeader><EmptyMedia variant="icon"><Inbox/></EmptyMedia><EmptyTitle>{title}</EmptyTitle><EmptyDescription>{text}</EmptyDescription></EmptyHeader></Empty>}
function RecordTable({rows,page,label,edit,archive,detail}:{rows:RecordRow[];page:PageDef;label:(id:any)=>string;edit:(r:RecordRow)=>void;archive:(r:RecordRow)=>void;detail:(r:RecordRow)=>void}){const sourceFields=fieldsFor(page);const fields=(page.entity==='students'?['name','phone','group','moderator','paymentDate','source'].map(k=>sourceFields.find(f=>f.key===k)).filter(Boolean) as Field[]:sourceFields).filter(f=>!['textarea','file','permissions','checkbox','color','parts'].includes(f.type??'')).slice(0,page.entity==='students'?7:8);return <div className="table-panel"><Table><TableHeader><TableRow><TableHead className="number-cell">№</TableHead>{fields.map(f=><TableHead key={f.key}>{f.label}</TableHead>)}{page.entity==='students'&&<TableHead>Holati</TableHead>}<TableHead className="action-cell"/></TableRow></TableHeader><TableBody>{rows.map((r,i)=><TableRow key={r.id}><TableCell className="number-cell">{i+1}</TableCell>{fields.map((f,j)=><TableCell key={f.key}>{f.key==='status'||f.key==='direction'?<span className={'status-chip '+(r.data[f.key]==='Kirim'||r.data[f.key]==='Faol'||r.data[f.key]==='Keldi'?'green':r.data[f.key]==='Chiqim'||r.data[f.key]==='Sababsiz'?'red':'blue')}>{r.data[f.key]??'—'}</span>:j===0&&(!page.readonly||page.entity==='students')?<button className="record-name" onClick={()=>page.entity==='students'?detail(r):edit(r)}>{f.type==='relation'?label(r.data[f.key]):r.data[f.key]||'—'}{page.entity==='students'&&' '+(r.data.surname??'')}</button>:f.type==='relation'?label(r.data[f.key]):f.type==='number'?number(r.data[f.key]):f.type==='tel'&&r.data[f.key]?<a href={'tel:'+r.data[f.key]}>{r.data[f.key]}</a>:r.data[f.key]||'—'}</TableCell>)}{page.entity==='students'&&<TableCell><span className={'status-chip '+(r.data.status==='Arxiv'?'gray':r.data.status==='Muzlatilgan'?'blue':'green')}>{r.data.status||'Faol'}</span></TableCell>}<TableCell><DropdownMenu><DropdownMenuTrigger className="icon-button" aria-label="Yozuv amallari"><MoreHorizontal size={17}/></DropdownMenuTrigger><DropdownMenuContent align="end">{page.entity==='transactions'&&!r.deleted&&r.data.direction==='Kirim'&&<DropdownMenuItem onClick={()=>requestReceipt(r,label(r.data.student))}>Chekni chiqarish</DropdownMenuItem>}{page.entity==='students'&&<DropdownMenuItem onClick={()=>detail(r)}>Profilni ochish</DropdownMenuItem>}{!page.readonly&&!r.data.calculation&&!r.data.payrollId&&!r.data.sourceAttendance&&!r.data.rewardId&&<><DropdownMenuItem onClick={()=>edit(r)}><Pencil size={14}/>Tahrirlash</DropdownMenuItem><DropdownMenuItem onClick={()=>archive(r)}><Archive size={14}/>{r.deleted?'Tiklash':'Arxivlash'}</DropdownMenuItem></>}{page.kind==='cancelled'&&<DropdownMenuItem onClick={()=>archive(r)}><RotateCcw size={14}/>Tiklash</DropdownMenuItem>}{page.readonly&&page.entity!=='students'&&page.kind!=='cancelled'&&<DropdownMenuItem disabled>Faqat ko‘rish</DropdownMenuItem>}</DropdownMenuContent></DropdownMenu></TableCell></TableRow>)}</TableBody></Table>{!rows.length&&<EmptyState text={page.readonly?'Hozircha ushbu hisobot uchun ma’lumot mavjud emas.':'Yangi yozuv qo‘shing yoki qidiruv va filtrlarni o‘zgartiring.'}/>}</div>}
function RecordForm({state,records,label,close,save}:{state:EditState;records:RecordRow[];label:(id:any)=>string;close:()=>void;save:any}){
 const fields=fieldsFor(state.page).filter(f=>state.page.entity!=='installments'||!['amount','date'].includes(f.key));const [data,setData]=useState<Record<string,any>>(()=>{const d={...state.initial,...state.record?.data};if(state.page.entity==='installments'&&!d.parts)d.parts=JSON.stringify([{amount:Number(d.amount||0),date:d.date||isoDate(),note:''}]);for(const f of fields){if(d[f.key]===undefined){if(f.type==='checkbox')d[f.key]=false;else if(f.type==='color')d[f.key]='#1847FF';else if(f.type==='select'&&f.options)d[f.key]=f.options[0];else if(f.type==='date'&&f.key==='date')d[f.key]=isoDate();}}return d});const [saving,setSaving]=useState(false),[uploading,setUploading]=useState(''),[error,setError]=useState(''),[nested,setNested]=useState<{page:PageDef;field:string}|null>(null);
 const change=(key:string,value:any)=>setData(d=>({...d,[key]:value}));
 async function submit(e:React.FormEvent){e.preventDefault();setSaving(true);setError('');try{let values={...data};if(state.page.entity==='installments'&&values.parts){const parts=JSON.parse(values.parts);values.amount=parts.reduce((n:number,p:any)=>n+Number(p.amount||0),0);values.date=parts.map((p:any)=>p.date).sort()[0]||values.date;}await save(state.page.entity,values,state.record);toast.success(state.record?'O‘zgarishlar saqlandi':'Yozuv qo‘shildi');close()}catch(e:any){setError(e.message)}finally{setSaving(false)}}
 const upload=async(key:string,file?:File)=>{if(!file)return;setUploading(key);try{const form=new FormData();form.append('file',file);const r=await fetch('/api/crm/files',{method:'POST',body:form});const v:any=await r.json();if(!r.ok)throw Error(v.error);change(key,v.url);toast.success('Fayl yuklandi')}catch(e:any){toast.error(e.message)}finally{setUploading('')}};
 return <RecordOverlay sheet={state.page.entity==='installments'} close={()=>!saving&&close()} large={fields.length>10}><DialogHeader><DialogTitle>{state.page.title} — {state.record?'tahrirlash':'qo‘shish'}</DialogTitle><DialogDescription>Yulduzcha bilan belgilangan maydonlar majburiy.</DialogDescription></DialogHeader><form onSubmit={submit}><div className="form-grid">{fields.map(f=><div key={f.key} className={'form-field '+(['textarea','permissions'].includes(f.type??'')?'full-field':'')}><label htmlFor={'field-'+f.key}>{f.label}{f.required&&<em> *</em>}</label>{f.type==='textarea'?<Textarea id={'field-'+f.key} required={f.required} rows={4} value={data[f.key]??''} onChange={e=>change(f.key,e.target.value)}/>:f.type==='checkbox'?<div className="form-switch"><Switch id={'field-'+f.key} checked={!!data[f.key]} onCheckedChange={v=>change(f.key,v)}/><span>{data[f.key]?'Yoqilgan':'O‘chirilgan'}</span></div>:f.type==='permissions'?<div className="permissions-grid">{menus.map(m=><div key={m.title}><strong>{m.title}</strong>{['Ko‘rish','Qo‘shish','Tahrirlash','Arxivlash'].map(action=>{const key='permission:'+m.icon+':'+action;return <label key={key}><Checkbox checked={!!data[key]} onCheckedChange={v=>change(key,!!v)}/>{action}</label>})}</div>)}<p className="form-note full-field">Ruxsatlar serverda tekshiriladi. Xodimga kirish huquqini Xodimlar bo‘limida biriktiring.</p></div>:f.type==='parts'?<PartsField value={data[f.key]??'[]'} onChange={v=>change(f.key,v)}/>:f.type==='select'||f.type==='relation'?<><NativeSelect id={'field-'+f.key} required={f.required} value={data[f.key]??''} onChange={e=>change(f.key,e.target.value)}><option value="">Tanlang</option>{f.type==='relation'?records.filter(r=>r.entity===f.entity).map(r=><option key={r.id} value={r.id}>{label(r.id)}</option>):f.options?.map(o=><option key={o}>{o}</option>)}</NativeSelect>{f.type==='relation'&&pages.some(p=>p.entity===f.entity&&p.fields.length)&&<button type="button" className="inline-add" onClick={()=>setNested({page:pages.find(p=>p.entity===f.entity&&p.fields.length)!,field:f.key})}><Plus size={12}/>Yangi qo‘shish</button>}{f.type==='relation'&&!records.some(r=>r.entity===f.entity)&&<small className="form-note">Avval {pages.find(p=>p.entity===f.entity)?.title.toLowerCase()??'tegishli yozuv'} bo‘limida yozuv qo‘shing.</small>}</>:f.type==='file'?<div className="file-input"><input id={'field-'+f.key} type="file" accept="image/png,image/jpeg,image/webp,application/pdf,video/mp4" onChange={e=>upload(f.key,e.target.files?.[0])}/>{uploading===f.key?<small>Yuklanmoqda…</small>:data[f.key]?<a href={data[f.key]} target="_blank" rel="noreferrer">Yuklangan faylni ochish<ExternalLink size={12}/></a>:<small>JPG, PNG, WebP, PDF, MP4 · 20 MB gacha</small>}</div>:<Input id={'field-'+f.key} type={f.type??'text'} min={f.type==='number'&&!['latitude','longitude'].includes(f.key)?0:undefined} step={f.type==='number'?'any':undefined} required={f.required} value={data[f.key]??''} onChange={e=>change(f.key,f.type==='number'?(e.target.value===''?'':Number(e.target.value)):e.target.value)} placeholder={f.type==='tel'?'+998':''}/>}</div>)}</div>{state.page.entity==='salary'&&<p className="inline-notice">Avtomatik hisoblash uchun Ish haqi bo‘limidagi hisoblash panelidan foydalaning.</p>}{error&&<div className="form-error" role="alert">{error}</div>}<DialogFooter><Button type="button" variant="outline" onClick={close} disabled={saving}>Bekor qilish</Button><Button type="submit" disabled={saving||!!uploading}>{saving?<><LoaderCircle size={15} className="spin"/>Saqlanmoqda…</>:<><Check size={16}/>Saqlash</>}</Button></DialogFooter></form>{nested&&<RecordForm state={{page:nested.page}} records={records} label={label} close={()=>setNested(null)} save={async(entity:string,values:any,r?:RecordRow)=>{const created=await save(entity,values,r);change(nested.field,created.id);return created}}/>}</RecordOverlay>
}
function Home({records,onCreate,label,router}:{records:RecordRow[];onCreate:(p:PageDef)=>void;label:(id:any)=>string;router:any}){
 const count=(entity:string,condition?:(r:RecordRow)=>boolean)=>records.filter(r=>r.entity===entity&&(!condition||condition(r))).length;
 const cards=[['Buyurtmalar',count('orders'),'/orders/order-list/table',ClipboardList,'blue'],['Birinchi darsga keladiganlar',count('orders',r=>r.data.date===isoDate()),'/orders/come-orders',CalendarDays,'purple'],['Yangi o‘quvchilar',count('students',r=>Date.now()-new Date(r.created_at).getTime()<30*86400000),'/orders/new-student-list',UserRound,'green'],['Faol o‘quvchilar',count('students',r=>!r.data.status||r.data.status==='Faol'),'/students/active',GraduationCap,'blue'],['Buyurtmadan ketganlar',count('orders',r=>r.data.status==='Bekor qilindi'),'/analytics/order',ArrowUpRight,'orange'],['Yangi o‘quvchidan ketganlar','—','/statistics',ArrowUpRight,'red'],['Faol o‘quvchidan ketganlar','—','/statistics',ArrowUpRight,'red'],['Qarzdorlar',records.filter(r=>r.entity==='students'&&studentAccount(r.id,records).debt>0).length,'/reports/analytics/unpaid',Wallet,'orange'],['Guruhlar',count('groups'),'/group/groups',Users,'purple'],['Birinchi to‘lov qilganlar',new Set(records.filter(r=>r.entity==='transactions'&&r.data.direction==='Kirim'&&r.data.student).map(r=>r.data.student)).size,'/finance/transactions',CheckCircle2,'green'],['Muzlatilgan',count('students',r=>r.data.status==='Muzlatilgan'),'/students/student-list',Clock,'blue'],['Arxivlar',count('students',r=>r.data.status==='Arxiv'),'/students/archive',Archive,'gray']];
 return <><div className="stats-grid">{cards.map(([title,value,path,Icon,color]:any)=><button className="stat-card" key={title} onClick={()=>router.push(path)}><div className={'stat-icon '+color}><Icon size={19}/></div><div className="stat-text"><span>{title}</span><strong>{value}</strong></div><ChevronRight className="stat-arrow" size={15}/></button>)}</div><div className="section-heading"><h2>Dars jadvali</h2><Button variant="outline" onClick={()=>onCreate(findPage('/group/groups')!)}><Plus size={15}/>Guruh qo‘shish</Button></div><Schedule records={records} label={label} onEdit={()=>router.push('/group/groups')}/></>
}
function Schedule({records,label,onEdit}:{records:RecordRow[];label:(id:any)=>string;onEdit:(r:RecordRow)=>void}){
 const [day,setDay]=useState(new Date().getDay()),[mode,setMode]=useState('rooms'),[list,setList]=useState(false),[weekOffset,setWeekOffset]=useState(0);
 const settings=records.find(r=>r.entity==='settings'&&r.data.section==='system')?.data??{};const toMinutes=(v:string)=>{const [h,m]=v.split(':').map(Number);return h*60+m};const begin=toMinutes(settings.dayStart||'08:00'),end=toMinutes(settings.dayEnd||'22:00');
 const start=new Date();start.setDate(start.getDate()-start.getDay()+weekOffset*7);const dates=days.map((_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return d});const selected=dates[day];const columns=records.filter(r=>r.entity===(mode==='rooms'?'rooms':'employees'));const groups=records.filter(r=>r.entity==='groups'&&r.data.status!=='Arxiv'&&(!r.data.days||r.data.days==='Har kuni'||(r.data.days==='Toq kunlar'&&[1,3,5].includes(day))||(r.data.days==='Juft kunlar'&&[2,4,6].includes(day))||(r.data.days==='Dam olish kuni'&&[0,6].includes(day)))).filter(r=>(!r.data.startDate||r.data.startDate<=selected.toISOString().slice(0,10))&&(!r.data.endDate||r.data.endDate>=selected.toISOString().slice(0,10)));
 return <section className="schedule-panel"><div className="schedule-toolbar"><div className="week-navigation"><button aria-label="Oldingi hafta" className="icon-button" onClick={()=>setWeekOffset(x=>x-1)}><ChevronLeft size={16}/></button><strong>{start.toLocaleDateString('uz-UZ',{day:'numeric',month:'long'})}</strong><button aria-label="Keyingi hafta" className="icon-button" onClick={()=>setWeekOffset(x=>x+1)}><ChevronRight size={16}/></button><button className="today-button" onClick={()=>{setWeekOffset(0);setDay(new Date().getDay())}}>Bugun</button></div><div className="schedule-controls"><NativeSelect aria-label="Jadval ustunlari" value={mode} onChange={e=>setMode(e.target.value)}><option value="rooms">Xonalar bo‘yicha</option><option value="teachers">O‘qituvchi bo‘yicha</option></NativeSelect><button aria-label="Ko‘rinishni almashtirish" className="icon-button" onClick={()=>setList(v=>!v)}>{list?<LayoutGrid size={17}/>:<List size={17}/>}</button><button aria-label="To‘liq ekran" className="icon-button" onClick={e=>{const panel=e.currentTarget.closest('section');if(document.fullscreenElement)document.exitFullscreen();else panel?.requestFullscreen().catch(()=>toast.error('To‘liq ekran mavjud emas'))}}><Maximize2 size={16}/></button></div></div><div className="weekday-tabs">{days.map((d,i)=><button key={d} className={day===i?'active':''} onClick={()=>setDay(i)}><span>{d}</span><small>{dates[i].getDate()}</small></button>)}</div>{list?<div className="schedule-list">{groups.length?groups.map(r=><button key={r.id} onClick={()=>onEdit(r)}><span className="blue-text">{r.data.time||'Vaqt belgilanmagan'}</span><strong>{r.data.name}</strong><span>{label(r.data.room)}</span><span>{label(r.data.teacher)}</span></button>):<EmptyState title="Bu kunga darslar belgilanmagan" text="Guruhga dars kunlari, xona va vaqt qo‘shing."/>}</div>:<div className="timetable-scroll"><div className="timetable" style={{gridTemplateColumns:`64px repeat(${Math.max(columns.length,1)}, minmax(160px,1fr))`}}><div className="time-heading"><Clock size={15}/></div>{columns.length?columns.map(r=><div className="room-heading" key={r.id}>{label(r.id)}</div>):<div className="room-heading">{mode==='rooms'?'Xonalar hali qo‘shilmagan':'O‘qituvchilar hali qo‘shilmagan'}</div>}{Array.from({length:Math.max(0,Math.min(48,Math.ceil((end-begin)/30)))},(_,i)=>{const mins=begin+i*30,time=String(Math.floor(mins/60)).padStart(2,'0')+':'+String(mins%60).padStart(2,'0');return <ScheduleRow key={time} time={time} columns={columns} groups={groups} mode={mode} onEdit={onEdit}/>})}</div></div>}</section>
}
function ScheduleRow({time,columns,groups,mode,onEdit}:{time:string;columns:RecordRow[];groups:RecordRow[];mode:string;onEdit:(r:RecordRow)=>void}){return <><div className="time-label">{time}</div>{(columns.length?columns:[{id:'none'} as RecordRow]).map(c=><div className="time-cell" key={c.id}>{groups.filter(g=>g.data[mode==='rooms'?'room':'teacher']===c.id&&g.data.time>=time&&g.data.time<(String(Math.floor((Number(time.slice(0,2))*60+Number(time.slice(3))+30)/60)).padStart(2,'0')+':'+String((Number(time.slice(3))+30)%60).padStart(2,'0'))).map(g=><button className="lesson" key={g.id} onClick={()=>onEdit(g)}><strong>{g.data.name}</strong><span>{g.data.time}–{g.data.endTime||'…'}</span></button>)}</div>)}</>}
function Kanban({rows,edit,label}:{rows:RecordRow[];edit:(r:RecordRow)=>void;label:(id:any)=>string}){return <div className="kanban">{['Yangi','Imtihonga yozildi','Test yechdi','Shartnoma','Bekor qilindi'].map((s,i)=><section key={s} className={'kanban-column col-'+i}><h3><i/>{s}<span>{rows.filter(r=>r.data.status===s).length}</span></h3>{rows.filter(r=>r.data.status===s).map(r=><button className="lead-card" key={r.id} onClick={()=>edit(r)}><strong>{label(r.data.student)}</strong><span>{label(r.data.course)}</span><small><CalendarDays size={12}/>{r.data.date||'Sana belgilanmagan'}</small></button>)}{!rows.some(r=>r.data.status===s)&&<p className="column-empty">Buyurtmalar yo‘q</p>}</section>)}</div>}
function TaskBoard({rows,label,edit,create,save}:{rows:RecordRow[];label:(id:any)=>string;edit:(r:RecordRow)=>void;create:()=>void;save:any}){const [busy,setBusy]=useState('');return <div className="task-board">{['Muddati o‘tgan','Bugun','Kelgusi','Bajarilgan'].map((title,i)=>{const tasks=rows.filter(r=>i===3?r.data.status==='Bajarilgan':r.data.status!=='Bajarilgan'&&(i===0?r.data.date<isoDate():i===1?r.data.date===isoDate():r.data.date>isoDate()));return <section key={title} className="task-column"><h3><span className={'task-dot dot-'+i}/>{title}<span className="count">{tasks.length}</span><button aria-label="Topshiriq qo‘shish" onClick={create}><Plus size={16}/></button></h3>{tasks.map(r=><article className="task-card" key={r.id}><div><Checkbox aria-label="Bajarilgan deb belgilash" disabled={busy===r.id} checked={r.data.status==='Bajarilgan'} onCheckedChange={async checked=>{setBusy(r.id);try{await save('tasks',{...r.data,status:checked?'Bajarilgan':'Yangi'},r);toast.success('Holat yangilandi')}catch(e:any){toast.error(e.message)}finally{setBusy('')}}}/><button onClick={()=>edit(r)}>{r.data.name}</button></div><p>{r.data.note}</p><footer><span><Clock size={12}/>{r.data.date} {r.data.time}</span><span className="tiny-avatar" title={label(r.data.moderator)}>{label(r.data.moderator).slice(0,1)}</span></footer></article>)}{!tasks.length&&<p className="column-empty">Topshiriqlar mavjud emas</p>}</section>})}</div>}
function AttendanceSummary({rows}:{rows:RecordRow[]}){return <div className="mini-stats">{['Keldi','Sababli','Sababsiz','Birinchi dars','Muzlatilgan'].map(s=><div key={s}><span>{s}</span><strong>{rows.filter(r=>r.data.status===s).length}</strong></div>)}</div>}
function Statistics({records}:{records:RecordRow[]}){return <div className="statistics-page"><div className="mini-stats">{[['students','O‘quvchilar'],['groups','Guruhlar'],['employees','Xodimlar'],['courses','Kurslar'],['branches','Filiallar']].map(([entity,title])=><div key={entity}><span>{title}</span><strong>{records.filter(r=>r.entity===entity).length}</strong></div>)}</div><div className="panel"><h2>O‘quvchilar holati</h2>{['Faol','Muzlatilgan','Arxiv'].map(s=>{const count=records.filter(r=>r.entity==='students'&&(r.data.status||'Faol')===s).length;const total=records.filter(r=>r.entity==='students').length;return <div key={s} className="bar-row"><span>{s}</span><div><i style={{width:(total?count/total*100:0)+'%'}}/></div><strong>{count}</strong></div>})}</div></div>}
function Funnel({records}:{records:RecordRow[]}){return <div className="panel funnel"><h2>Buyurtmalar bosqichlari</h2>{['Yangi','Imtihonga yozildi','Test yechdi','Shartnoma','Bekor qilindi'].map((s,i)=>{const count=records.filter(r=>r.data.status===s).length;return <div key={s} className="bar-row"><span>{s}</span><div><i style={{width:(records.length?count/records.length*100:0)+'%',opacity:1-i*.12}}/></div><strong>{count}</strong></div>})}<p className="form-note">Kiritilgan buyurtmalarning joriy holati. Bosqichlar o‘rtasidagi tarixiy konversiya hali hisoblanmaydi.</p></div>}
function Finance({rows,kind}:{rows:RecordRow[];kind:string}){
 const [year,setYear]=useState(new Date().getFullYear());const selected=rows.filter(r=>r.data.date?.startsWith(String(year)));const sum=(dir:string,month?:number)=>selected.filter(r=>r.data.direction===dir&&(month===undefined||Number(r.data.date?.slice(5,7))===month+1)).reduce((n,r)=>n+Number(r.data.amount||0),0);const income=sum('Kirim'),expense=sum('Chiqim');const months=['Yan','Fev','Mar','Apr','May','Iyun','Iyul','Avg','Sen','Okt','Noy','Dek'];const max=Math.max(1,...months.flatMap((_,i)=>[sum('Kirim',i),sum('Chiqim',i)]));
 return <div><div className="profile-actions"><Button variant="outline" onClick={()=>exportRows('Moliya '+year,['Ko‘rsatkich',...months,'Jami'],['Kirim','Chiqim','Sof pul oqimi'].map(s=>[s,...months.map((_,i)=>s==='Sof pul oqimi'?sum('Kirim',i)-sum('Chiqim',i):sum(s,i)),s==='Sof pul oqimi'?income-expense:sum(s)]))}><Download size={15}/>Hisobotni eksport qilish</Button></div><div className="finance-top"><div className="money-card"><span><ArrowDownLeft size={16}/>Jami kirim</span><strong>{number(income)} <small>UZS</small></strong></div><div className="money-card"><span><ArrowUpRight size={16}/>Jami chiqim</span><strong>{number(expense)} <small>UZS</small></strong></div><div className="money-card"><span><Wallet size={16}/>Sof pul oqimi</span><strong>{number(income-expense)} <small>UZS</small></strong></div></div><div className="panel finance-chart"><div className="section-heading"><h2>{kind==='pnl'?'Kirim va chiqim jamlanmasi':kind==='cashflow'?'Pul oqimi':'Kirim va chiqim dinamikasi'}</h2><NativeSelect value={year} onChange={e=>setYear(Number(e.target.value))}>{Array.from({length:7},(_,i)=>new Date().getFullYear()-3+i).map(y=><option key={y}>{y}</option>)}</NativeSelect></div>{kind==='finance'?<><div className="chart-legend"><span><i/>Kirim</span><span><i/>Chiqim</span></div><div className="bar-chart">{months.map((month,i)=><div className="month-bar" key={month}><div className="bar-pair"><div title={'Kirim: '+number(sum('Kirim',i))} style={{height:Math.max(sum('Kirim',i)/max*180,2)}}/><div title={'Chiqim: '+number(sum('Chiqim',i))} style={{height:Math.max(sum('Chiqim',i)/max*180,2)}}/></div><span>{month}</span></div>)}</div></>:null}<Table><TableHeader><TableRow><TableHead>Ko‘rsatkich</TableHead>{months.map(m=><TableHead key={m}>{m}</TableHead>)}<TableHead>Jami</TableHead></TableRow></TableHeader><TableBody>{['Kirim','Chiqim','Sof pul oqimi'].map(s=><TableRow key={s}><TableCell>{s}</TableCell>{months.map((m,i)=><TableCell key={m}>{number(s==='Sof pul oqimi'?sum('Kirim',i)-sum('Chiqim',i):sum(s,i))}</TableCell>)}<TableCell><strong>{number(s==='Sof pul oqimi'?income-expense:sum(s))}</strong></TableCell></TableRow>)}</TableBody></Table><p className="form-note">Faqat kiritilgan tranzaksiyalar jamlanadi. {kind==='pnl'?'To‘liq P&L uchun hisoblangan daromad, majburiyat va xarajatlarni tan olish qoidalari hali ulanmagan.':kind==='cashflow'?'Operatsion, investitsion va moliyaviy faoliyat bo‘yicha tasnif hali ulanmagan.':'Bekor qilingan tranzaksiyalar hisobga olinmaydi.'}</p></div></div>
}
function SettingsPage({page,records,save}:{page:PageDef;records:RecordRow[];save:any}){const section=page.path.split('/').pop()!;const existing=records.find(r=>r.entity==='settings'&&r.data.section===section);const [data,setData]=useState<Record<string,any>>({}),[tab,setTab]=useState(''),[saving,setSaving]=useState(false);const groups=settingsSections[section]??{};useEffect(()=>{setData(existing?.data??{section,timezone:'Asia/Tashkent',dayStart:'08:00',dayEnd:'22:00',currency:'UZS',maxGrade:5,tablePageSize:'20',filterStyle:'Oddiy'});setTab(Object.keys(groups)[0]??'')},[section,existing?.id]);const changed=JSON.stringify(data)!==JSON.stringify(existing?.data??{});
 return <div className="settings-layout"><aside className="settings-nav">{Object.keys(groups).map(s=><button key={s} className={s===tab?'active':''} onClick={()=>setTab(s)}>{s}<ChevronRight size={14}/></button>)}{section==='system'&&<Link href="/login">Kirish sahifasi<ExternalLink size={14}/></Link>}</aside><section className="panel settings-panel"><div className="section-heading"><h2>{tab}</h2><Button disabled={saving||!changed} onClick={async()=>{setSaving(true);try{await save('settings',{...data,section},existing);toast.success('Sozlamalar saqlandi')}catch(e:any){toast.error(e.message)}finally{setSaving(false)}}}>{saving?'Saqlanmoqda…':'Saqlash'}</Button></div>{(groups[tab]??[]).map(f=><div className="setting-row" key={f.key}><label htmlFor={'setting-'+f.key}>{f.label}</label>{f.type==='switch'?<Switch id={'setting-'+f.key} checked={!!data[f.key]} onCheckedChange={v=>setData(d=>({...d,[f.key]:v}))}/>:f.type==='select'?<NativeSelect id={'setting-'+f.key} value={data[f.key]??''} onChange={e=>setData(d=>({...d,[f.key]:e.target.value}))}><option value="">Tanlang</option>{f.options?.map(o=><option key={o}>{o}</option>)}</NativeSelect>:<Input id={'setting-'+f.key} type={f.type??'text'} min={0} value={data[f.key]??''} onChange={e=>setData(d=>({...d,[f.key]:f.type==='number'?Number(e.target.value):e.target.value}))}/>}</div>)}<div className="inline-notice"><Settings size={16}/><span>Bu yerda konfiguratsiya saqlanadi. Jadval qatorlari soni, dars vaqti, majburiy o‘quvchi maydonlari va maksimal baho qo‘llanadi; avtomatik SMS, maosh, chegirma, Face ID va boshqa avtomatlashtirish qoidalari hali ulanmagan.</span></div></section></div>
}
function Integrations({onInfo}:{onInfo:(v:{title:string;content:string})=>void}){const [notification,setNotification]=useState<any>(null);useEffect(()=>{fetch('/api/crm/notification-status').then(async r=>{if(r.ok)setNotification(await r.json())}).catch(()=>{})},[]);return <div className="integrations-page">{integrations.map(([category,...providers])=><section key={category}><h2>{category}</h2><div className="integration-grid">{providers.map((p,i)=><article className="integration-card" key={p}><div className={'provider-icon provider-'+i}>{p.slice(0,2)}</div><div><h3>{p}</h3><span className={'status-chip '+(p==='Telegram'&&notification?.telegramConfigured?'green':'gray')}>{p==='Telegram'&&notification?.telegramConfigured?'Sozlangan':'Ulanmagan'}</span></div><Button variant="outline" onClick={()=>onInfo({title:p+' integratsiyasi',content:p==='Telegram'?'Markazning alohida bot tokeni va chat IDsi serverda sozlanadi. To‘lov va topshiriq xabarlari navbat orqali yuboriladi. '+(notification?.messages?.length?notification.messages.length+' ta oxirgi xabar qayd etilgan.':'Hozircha yuborish tarixi yo‘q.'):'Ushbu xizmat bilan aloqa hali amalga oshirilmagan. Ulanish uchun provayder hisobi, API konfiguratsiyasi va server integratsiyasi kerak. Bu oynada maxfiy kalit kiritish yoki xizmatni ulash bajarilmaydi.'})}>Batafsil<ChevronRight size={14}/></Button></article>)}</div></section>)}</div>}
function StudentDetail({student,records,events,label,close,edit,onCreate}:{student:RecordRow;records:RecordRow[];events:any[];label:(id:any)=>string;close:()=>void;edit:()=>void;onCreate:(p:PageDef)=>void}){const [tab,setTab]=useState('Umumiy');const tabs=['Umumiy','Guruhlar','To‘lovlar','Davomat','Topshiriqlar','Qo‘ng‘iroqlar','Shartnoma','Manzil','Faollik','Coin','LTV','SMS'];const related=(entity:string)=>records.filter(r=>r.entity===entity&&r.data.student===student.id);const paid=related('transactions').filter(r=>r.data.direction==='Kirim').reduce((s,r)=>s+Number(r.data.amount||0),0);const g=records.find(r=>r.id===student.data.group);
 return <Dialog open onOpenChange={v=>!v&&close()}><DialogContent className="student-dialog"><DialogHeader><DialogTitle>O‘quvchi profili</DialogTitle><DialogDescription>{student.data.name} {student.data.surname}</DialogDescription></DialogHeader><div className="student-layout"><aside className="student-card"><div className="student-avatar">{student.data.name?.slice(0,1)}</div><h2>{student.data.name} {student.data.surname}</h2><span className="status-chip green">{student.data.status||'Faol'}</span><div className="student-contact"><a href={'tel:'+student.data.phone}><Phone size={15}/>{student.data.phone||'Telefon kiritilmagan'}</a><span><Mail size={15}/>{student.data.email||'Email kiritilmagan'}</span><span><CalendarDays size={15}/>{student.data.birthDate||'Sana kiritilmagan'}</span></div><div className="profile-summary"><span>To‘lovlar jami<strong>{number(paid)} UZS</strong></span><span>Mas’ul xodim<strong>{label(student.data.moderator)}</strong></span></div><Button className="w-full" onClick={edit}><Pencil size={15}/>Tahrirlash</Button></aside><section className="student-main"><Tabs value={tab} onValueChange={setTab}><TabsList className="profile-tabs">{tabs.map(t=><TabsTrigger value={t} key={t}>{t}</TabsTrigger>)}</TabsList><TabsContent value="Umumiy"><div className="detail-grid">{studentFields.filter(f=>!['name','surname'].includes(f.key)).map(f=><div key={f.key}><span>{f.label}</span><strong>{f.type==='relation'?label(student.data[f.key]):student.data[f.key]||'—'}</strong></div>)}</div></TabsContent><TabsContent value="Guruhlar">{g?<div className="profile-group"><div className="stat-icon blue"><Users size={22}/></div><h3>{g.data.name}</h3><p>{label(g.data.course)} · {label(g.data.teacher)}</p><span>{g.data.days} · {g.data.time}</span></div>:<EmptyState title="Guruh biriktirilmagan" text="Tahrirlash oynasidan guruh tanlang."/>}</TabsContent><TabsContent value="To‘lovlar"><SmallList rows={related('transactions')} fields={['name','date','amount','direction']} label={label}/></TabsContent><TabsContent value="Davomat"><SmallList rows={related('attendance')} fields={['date','group','status','note']} label={label}/></TabsContent><TabsContent value="Topshiriqlar"><EmptyState title="O‘quvchi topshiriqlari hali ulanmagan" text="Umumiy topshiriqlar bo‘limida xodimga topshiriq berishingiz mumkin."/></TabsContent><TabsContent value="Qo‘ng‘iroqlar"><EmptyState title="Qo‘ng‘iroqlar integratsiyasi ulanmagan" text="Telefoniya ulangandan keyin qo‘ng‘iroq tarixi ko‘rsatiladi."/></TabsContent><TabsContent value="Shartnoma"><ContractPreview student={student} templates={records.filter(r=>r.entity==='contract-templates')}/></TabsContent><TabsContent value="Manzil"><div className="address-card"><MapPin size={25}/><h3>{student.data.address||'Manzil kiritilmagan'}</h3><Button variant="outline" onClick={edit}>Manzilni tahrirlash</Button></div></TabsContent><TabsContent value="Faollik"><div className="activity-list">{events.filter(e=>e.record_id===student.id).map((e,i)=><div key={i}><i/><div><strong>{({create:'O‘quvchi qo‘shildi',update:'Ma’lumotlar yangilandi',archive:'Arxivlandi',restore:'Tiklandi'} as any)[e.action]??e.action}</strong><span>{new Date(e.created_at).toLocaleString('uz-UZ')}</span></div></div>)}</div></TabsContent>{['Coin','LTV','SMS'].map(t=><TabsContent value={t} key={t}><EmptyState title={t+' hali ulanmagan'} text={t==='Coin'?'Coin qoidalari asl tizimda tekshirilmagan.':t==='LTV'?'LTV hisoblash formulasi hali tasdiqlanmagan.':'SMS provayder integratsiyasi talab qilinadi.'}/></TabsContent>)}</Tabs></section></div></DialogContent></Dialog>
}
function SmallList({rows,fields,label}:{rows:RecordRow[];fields:string[];label:(id:any)=>string}){return rows.length?<div className="small-list">{rows.map(r=><div key={r.id}>{fields.map(f=><span key={f}>{f==='amount'?number(r.data[f]):label(r.data[f])}</span>)}</div>)}</div>:<EmptyState text="O‘quvchiga tegishli yozuvlar qo‘shilganda shu yerda ko‘rsatiladi."/>}
function ContractPreview({student,templates}:{student:RecordRow;templates:RecordRow[]}){const [id,setId]=useState('');const template=templates.find(t=>t.id===id);const content=template?.data.content?.replaceAll('{{name}}',[student.data.name,student.data.surname].filter(Boolean).join(' ')).replaceAll('{{date}}',isoDate()).replaceAll('{{amount}}','[summa]');return <div><NativeSelect aria-label="Shartnoma shabloni" value={id} onChange={e=>setId(e.target.value)}><option value="">Shartnoma shablonini tanlang</option>{templates.map(t=><option key={t.id} value={t.id}>{t.data.name}</option>)}</NativeSelect>{template?<><article className="contract-preview"><h2>{template.data.name}</h2><p>{content}</p></article><Button variant="outline" onClick={()=>{const blob=new Blob([content],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='Shartnoma.txt';a.click();URL.revokeObjectURL(url)}}><Download size={15}/>Matnni yuklash</Button></>:<EmptyState title="Shablon tanlang" text="Shablonlar O‘quv bo‘limi → Shartnoma shablonlari orqali qo‘shiladi."/>}</div>}
function DerivedReport({page,records,targets,label}:{page:PageDef;records:RecordRow[];targets:RecordRow[];label:(id:any)=>string}){
 let headers:string[]=[],rows:any[][]=[];
 if(page.kind==='salary'){
 headers=['Xodim','Oy','Asosiy maosh','Bonus','Avans','Jarima','Hisoblangan qoldiq'];
 rows=targets.filter(r=>r.entity==='salary').map(r=>[label(r.data.moderator),r.data.month,number(r.data.base),number(r.data.bonus),number(r.data.advance),number(r.data.penalty),number(Number(r.data.base||0)+Number(r.data.bonus||0)-Number(r.data.advance||0)-Number(r.data.penalty||0))]);
 }else if(page.path==='/analytics/teacher'){
 headers=['O‘qituvchi','Guruhlar','Faol o‘quvchilar'];
 rows=targets.filter(r=>r.entity==='employees').map(t=>{const groups=records.filter(r=>r.entity==='groups'&&r.data.teacher===t.id);return [label(t.id),groups.length,records.filter(r=>r.entity==='students'&&groups.some(g=>groupIds(r,records).includes(g.id))&&(r.data.status||'Faol')==='Faol').length]});
 }else if(page.path==='/analytics/moderator/student'){
 headers=['Moderator','Jami','Faol','Muzlatilgan','Arxiv'];rows=targets.filter(r=>r.entity==='employees').map(t=>{const students=records.filter(r=>r.entity==='students'&&r.data.moderator===t.id);return [label(t.id),students.length,...['Faol','Muzlatilgan','Arxiv'].map(s=>students.filter(r=>(r.data.status||'Faol')===s).length)]});
 }else if(page.path==='/analytics/rooms'){
 headers=['Xona','Sig‘im','Biriktirilgan guruhlar','O‘quvchilar'];rows=targets.filter(r=>r.entity==='rooms').map(room=>{const groups=records.filter(r=>r.entity==='groups'&&r.data.room===room.id);return [room.data.name,room.data.capacity||'—',groups.length,records.filter(r=>r.entity==='students'&&groups.some(g=>groupIds(r,records).includes(g.id))).length]});
 }else{
 headers=['Ketish sababi','O‘quvchilar'];const left=records.filter(r=>r.entity==='students'&&r.data.status==='Arxiv');rows=[...new Set(left.map(r=>r.data.exitReason||'Sabab kiritilmagan'))].map(reason=>[reason,left.filter(r=>(r.data.exitReason||'Sabab kiritilmagan')===reason).length]);
 }
 return <section className="panel"><div className="profile-actions"><Button variant="outline" onClick={()=>exportRows(page.title,headers,rows)}><Download size={15}/>Hisobotni eksport qilish</Button></div><Table><TableHeader><TableRow>{headers.map(h=><TableHead key={h}>{h}</TableHead>)}</TableRow></TableHeader><TableBody>{rows.map((row,i)=><TableRow key={i}>{row.map((v,j)=><TableCell key={j}>{v}</TableCell>)}</TableRow>)}</TableBody></Table>{!rows.length&&<EmptyState title="Hisobot uchun ma’lumot yo‘q" text="Tegishli bo‘limlarda yozuvlar qo‘shilganda hisobot shakllanadi."/>}<p className="form-note">{page.kind==='salary'?'Qo‘lda kiritilgan maosh + bonus − avans − jarima. Asl tizimning avtomatik maosh formulasi ulanmagan.':'Joriy yozuvlar bo‘yicha jamlanma. Tarixiy davrlar bo‘yicha o‘zgarish hisoblanmaydi.'}</p></section>
}
function RecordOverlay({children,close,large,sheet}:{children:React.ReactNode;close:()=>void;large:boolean;sheet:boolean}){return sheet?<Sheet open onOpenChange={v=>!v&&close()}><SheetContent className="installment-sheet">{children}</SheetContent></Sheet>:<Dialog open onOpenChange={v=>!v&&close()}><DialogContent className={'record-dialog '+(large?'large-dialog':'')}>{children}</DialogContent></Dialog>}
function PartsField({value,onChange}:{value:string;onChange:(v:string)=>void}){let parts:any[]=[];try{parts=JSON.parse(value)}catch{}const update=(i:number,key:string,v:any)=>onChange(JSON.stringify(parts.map((p,index)=>index===i?{...p,[key]:v}:p)));return <div className="parts-field">{parts.map((p,i)=><div key={i}><strong>{i+1}-to‘lov</strong><label>Qiymat<Input type="number" min="1" value={p.amount} required onChange={e=>update(i,'amount',Number(e.target.value))}/></label><label>Sana<Input type="date" value={p.date} required onChange={e=>update(i,'date',e.target.value)}/></label><label>Izoh<Input value={p.note} onChange={e=>update(i,'note',e.target.value)}/></label><button className="inline-add" type="button" onClick={()=>onChange(JSON.stringify(parts.filter((_,j)=>j!==i)))}>Qismni olib tashlash</button></div>)}<Button type="button" variant="outline" onClick={()=>onChange(JSON.stringify([...parts,{amount:0,date:isoDate(),note:''}]))}><Plus size={14}/>Shartnoma qismini qo‘shish</Button><strong>Jami: {number(parts.reduce((s,p)=>s+Number(p.amount||0),0))} UZS</strong></div>}
